import exceljs from "exceljs";
import type {
  AuditTrailFullData,
  TimelineAuditStep,
} from "@tepian-k3/types/pengujian/audit-trail.types";

// ##################
// authored (generated by AI, Jul 28 2026 03:44 WITA)
// ##################

/**
 * Membangun file Excel (.xlsx) Rekap Audit Trail Pengujian K3.
 *
 * Menggunakan 3 Sheet:
 * 1. Rekap Pelanggan & Order
 * 2. Lokasi & Parameter Pengujian
 * 3. Timeline Audit & Durasi Proses (Format DD-MM-YYYY & HH-MM-SS)
 */
export async function buildAuditTrailWorkbook(
  data: AuditTrailFullData,
): Promise<Buffer> {
  const workbook = new exceljs.Workbook();
  workbook.creator = "Tepian K3 System";
  workbook.lastModifiedBy = "Tepian K3 System";
  workbook.created = new Date();

  const HEADER_FILL: exceljs.Fill = {
    type: "pattern",
    pattern: "solid",
    fgColor: { argb: "1E40AF" }, // Blue-800
  };

  const HEADER_FONT: Partial<exceljs.Font> = {
    color: { argb: "FFFFFF" },
    bold: true,
    size: 11,
  };

  const BORDER_STYLE: Partial<exceljs.Borders> = {
    top: { style: "thin", color: { argb: "E2E8F0" } },
    left: { style: "thin", color: { argb: "E2E8F0" } },
    bottom: { style: "thin", color: { argb: "E2E8F0" } },
    right: { style: "thin", color: { argb: "E2E8F0" } },
  };

  // ==================== SHEET 1: REKAP PELANGGAN & ORDER ====================
  const ws1 = workbook.addWorksheet("📊 Rekap Pelanggan & Order");
  ws1.columns = [
    { header: "Atribut", key: "key", width: 32 },
    { header: "Nilai Informasi", key: "value", width: 65 },
  ];

  // Header styling
  const hRow1 = ws1.getRow(1);
  hRow1.eachCell((cell) => {
    cell.fill = HEADER_FILL;
    cell.font = HEADER_FONT;
    cell.alignment = { vertical: "middle", horizontal: "center" };
  });

  const customerRows = [
    { key: "Nomor Order", value: data.orderInfo.orderNumber },
    { key: "Status Pesanan", value: data.orderInfo.status.toUpperCase() },
    {
      key: "Status Persetujuan",
      value: data.orderInfo.approvalStatus.toUpperCase(),
    },
    {
      key: "Status Pembayaran",
      value: data.orderInfo.paymentStatus.toUpperCase(),
    },
    { key: "Jenis Pendanaan", value: data.orderInfo.fundingType.toUpperCase() },
    {
      key: "Total Biaya (Rp)",
      value: `Rp ${data.orderInfo.totalAmount.toLocaleString("id-ID")}`,
    },
    { key: "Nama Perusahaan / Customer", value: data.customerInfo.companyName },
    { key: "Alamat Perusahaan", value: data.customerInfo.companyAddress },
    { key: "KBLI", value: data.customerInfo.kbliName ?? "-" },
    {
      key: "Penanggung Jawab Pengujian",
      value: data.customerInfo.responsiblePerson,
    },
    { key: "Telepon PJ", value: data.customerInfo.responsiblePhone },
    { key: "Email PJ", value: data.customerInfo.responsibleEmail },
    { key: "Pimpinan Perusahaan", value: data.customerInfo.headOfCompany },
    { key: "Jabatan Pimpinan", value: data.customerInfo.headPosition },
    {
      key: "Status WLKP",
      value: data.customerInfo.wlkpStatus ? "Ada" : "Tidak Ada",
    },
    {
      key: "Bank Perusahaan",
      value: `${data.customerInfo.bankName} - ${data.customerInfo.bankAccount}`,
    },
    { key: "Catatan Pelanggan", value: data.orderInfo.customerNote ?? "-" },
  ];

  customerRows.forEach((item) => {
    const row = ws1.addRow(item);
    row.getCell("key").font = { bold: true };
    row.eachCell((cell) => {
      cell.border = BORDER_STYLE;
    });
  });

  ws1.views = [{ state: "frozen", ySplit: 1 }];

  // ==================== SHEET 2: LOKASI & PARAMETER ====================
  const ws2 = workbook.addWorksheet("📍 Lokasi & Parameter Pengujian");
  ws2.columns = [
    { header: "No", key: "no", width: 6 },
    { header: "Lokasi Pengujian", key: "location", width: 35 },
    { header: "Kabupaten/Kota", key: "regency", width: 25 },
    { header: "Kecamatan", key: "district", width: 25 },
    { header: "Parameter Pengujian", key: "parameter", width: 40 },
    { header: "Tipe Layanan", key: "serviceType", width: 18 },
    { header: "Jumlah (Titik/Sampel)", key: "quantity", width: 22 },
    { header: "Harga Satuan (Rp)", key: "price", width: 22 },
    { header: "Subtotal (Rp)", key: "subTotal", width: 25 },
  ];

  const hRow2 = ws2.getRow(1);
  hRow2.eachCell((cell) => {
    cell.fill = HEADER_FILL;
    cell.font = HEADER_FONT;
    cell.alignment = { vertical: "middle", horizontal: "center" };
  });

  data.locationsAndParameters.forEach(
    (
      item: AuditTrailFullData["locationsAndParameters"][number],
      idx: number,
    ) => {
      const row = ws2.addRow({
        no: idx + 1,
        location: item.locationName,
        regency: item.regencyName ?? "-",
        district: item.districtName ?? "-",
        parameter: item.parameterName,
        serviceType: item.serviceType.toUpperCase(),
        quantity: item.quantity,
        price: item.price,
        subTotal: item.subTotal,
      });

      row.getCell("no").alignment = { horizontal: "center" };
      row.getCell("quantity").alignment = { horizontal: "right" };
      row.getCell("price").numFmt = '"Rp "#,##0';
      row.getCell("subTotal").numFmt = '"Rp "#,##0';

      row.eachCell((cell) => {
        cell.border = BORDER_STYLE;
      });
    },
  );

  ws2.views = [{ state: "frozen", ySplit: 1 }];

  // ==================== SHEET 3: TIMELINE AUDIT & DURASI ====================
  const ws3 = workbook.addWorksheet("⏱️ Timeline & Audit Durasi");
  ws3.columns = [
    { header: "No Step", key: "stepNumber", width: 10 },
    { header: "Tahap Status", key: "statusLabel", width: 30 },
    { header: "Diubah Oleh", key: "changedByName", width: 25 },
    { header: "Email Pengubah", key: "changedByEmail", width: 30 },
    { header: "Tanggal (DD-MM-YYYY)", key: "dateFormatted", width: 22 },
    { header: "Waktu (HH-MM-SS)", key: "timeFormatted", width: 20 },
    { header: "Durasi Dari Step Sebelumnya", key: "durationText", width: 35 },
    {
      header: "Kode Durasi (DDd HHh MMm)",
      key: "durationFormatted",
      width: 28,
    },
    { header: "Catatan / Keterangan", key: "note", width: 45 },
  ];

  const hRow3 = ws3.getRow(1);
  hRow3.eachCell((cell) => {
    cell.fill = HEADER_FILL;
    cell.font = HEADER_FONT;
    cell.alignment = { vertical: "middle", horizontal: "center" };
  });

  data.timeline.steps.forEach((step: TimelineAuditStep) => {
    const row = ws3.addRow({
      stepNumber: step.stepNumber,
      statusLabel: step.statusLabel,
      changedByName: step.changedByName,
      changedByEmail: step.changedByEmail,
      dateFormatted: step.dateFormatted,
      timeFormatted: step.timeFormatted,
      durationText: step.durationFromPrevious.text,
      durationFormatted: step.durationFromPrevious.formatted,
      note: step.note ?? "-",
    });

    row.getCell("stepNumber").alignment = { horizontal: "center" };
    row.getCell("dateFormatted").alignment = { horizontal: "center" };
    row.getCell("timeFormatted").alignment = { horizontal: "center" };
    row.getCell("durationFormatted").alignment = { horizontal: "center" };

    row.eachCell((cell) => {
      cell.border = BORDER_STYLE;
    });
  });

  // Baris Tambahan: Summary Total Waktu Proses Keseluruhan
  ws3.addRow({});
  const summaryRow = ws3.addRow({
    stepNumber: "SUMMARY",
    statusLabel: "TOTAL WAKTU PROSES KESELURUHAN",
    dateFormatted: `Mulai: ${data.timeline.startDateFormatted}`,
    timeFormatted: `Selesai: ${data.timeline.endDateFormatted}`,
    durationText: data.timeline.totalDuration.text,
    durationFormatted: data.timeline.totalDuration.formatted,
    note: "Dihitung dari pembuatan order hingga tahap akhir",
  });

  summaryRow.eachCell((cell) => {
    cell.fill = {
      type: "pattern",
      pattern: "solid",
      fgColor: { argb: "FEF08A" }, // Yellow-200
    };
    cell.font = { bold: true, color: { argb: "854D0E" } };
    cell.border = {
      top: { style: "medium", color: { argb: "CA8A04" } },
      bottom: { style: "medium", color: { argb: "CA8A04" } },
    };
  });

  ws3.views = [{ state: "frozen", ySplit: 1 }];

  // Render ke Uint8Array / Buffer
  const arrayBuffer = await workbook.xlsx.writeBuffer();
  return Buffer.from(arrayBuffer);
}

